#!/usr/bin/env node
// Task 18: consolidated migration report, per the task's own required
// structure (legacy inventory / pricing / destinations / URLs / data
// issues). Read-only — derives entirely from
// data/maldives/migration/transfer-legacy-recovery.json and
// data/maldives/migration/redirect-map.json (both already generated by
// earlier Task 18/16 scripts). Nothing here is re-computed differently;
// it only summarizes numbers those scripts already produced, so it can
// never disagree with what actually got migrated.
//
// Writes: data/maldives/migration/task18-transfer-migration-report.json
// Usage: node scripts/generate-task18-migration-report.mjs

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

import { DATA_DIR, ROOT } from "./lib/legacy-shared.mjs";

const MIGRATION_DATA_DIR = path.join(DATA_DIR, "migration");

function main() {
  const recoveryPath = path.join(MIGRATION_DATA_DIR, "transfer-legacy-recovery.json");
  const redirectMapPath = path.join(MIGRATION_DATA_DIR, "redirect-map.json");
  if (!existsSync(recoveryPath) || !existsSync(redirectMapPath)) {
    console.error("Run scripts/rebuild-legacy-transfers.mjs --commit and scripts/build-redirect-map.mjs first.");
    process.exit(1);
  }
  const recovery = JSON.parse(readFileSync(recoveryPath, "utf8"));
  const redirectMap = JSON.parse(readFileSync(redirectMapPath, "utf8"));

  const ready = recovery.records.filter((r) => r.status === "ready");
  const excluded = recovery.records.filter((r) => r.status !== "ready");

  // ── Legacy inventory ─────────────────────────────────────────────────
  const exclusionReasons = {};
  for (const r of excluded) {
    const key = r.reason;
    exclusionReasons[key] = (exclusionReasons[key] ?? 0) + 1;
  }

  // ── Pricing ──────────────────────────────────────────────────────────
  const withPrice = ready.length; // every "ready" record has a real price by construction
  const withChildPrice = ready.filter((r) => r.childPrice !== null).length;
  const missingPrice = excluded.filter((r) => r.reason?.includes("No usable price")).length;

  // ── Destinations ─────────────────────────────────────────────────────
  const destinationSlugs = new Set(ready.map((r) => r.islandSlug));
  const newLocations = ready.filter((r) => r.isNewLocation);
  const newLocationSlugs = new Set(newLocations.map((r) => r.islandSlug));
  const existingLocationMatches = ready.filter((r) => !r.isNewLocation);
  // Duplicate destination = more than one legacy page resolving to the
  // same island (a real, intentional merge — e.g. two pages both
  // describing Centara Ras Fushi/Maniafaru — not a data error).
  const destinationPageCounts = new Map();
  for (const r of ready) destinationPageCounts.set(r.islandSlug, (destinationPageCounts.get(r.islandSlug) ?? 0) + 1);
  const mergedDestinations = Array.from(destinationPageCounts.entries())
    .filter(([, count]) => count > 1)
    .map(([slug, count]) => ({ islandSlug: slug, legacyPageCount: count }));

  // ── URLs ─────────────────────────────────────────────────────────────
  const transferUrlRecords = redirectMap.records.filter((r) => r.pageType === "transfer");
  const transferRedirects = transferUrlRecords.filter((r) => r.migrationStatus === "redirect" || r.migrationStatus === "consolidate");

  const report = {
    generatedAt: new Date().toISOString(),
    note:
      "Task 18. Every number here is derived from data/maldives/migration/transfer-legacy-recovery.json (the full " +
      "legacy transfer recovery pass) and redirect-map.json (Task 16, updated for Task 18's new destinations) — " +
      "never a separate estimate.",

    legacyInventory: {
      totalLegacyTransferPagesDiscovered: recovery.totalTransferPages,
      numberMigrated: ready.length,
      numberIntentionallyExcluded: excluded.length,
      exclusionReasons,
    },

    pricing: {
      routesWithPrice: withPrice,
      routesWithReturnPrice: 0,
      routesWithMissingPrice: missingPrice,
      routesWithChildPrice: withChildPrice,
      note:
        "No legacy transfer page stated a separately-sourced return price — the legacy booking-form JavaScript " +
        "simply doubles the one-way adult price for a 'Two Way' trip client-side (confirmed by reading that JS " +
        "directly), which is a UI convention, not real return-fare data, so no returnPrice was recorded or invented.",
      conflictingPrices: recovery.priceConflicts,
    },

    destinations: {
      totalDistinctDestinations: destinationSlugs.size,
      newLocationsCreated: newLocationSlugs.size,
      matchedToExistingLocations: existingLocationMatches.length,
      mergedDestinations,
    },

    urls: {
      legacyTransferUrlsDiscovered: recovery.totalTransferPages,
      newRoutesCreated: newLocationSlugs.size,
      redirectsCreated: transferRedirects.length,
      unresolvedLegacyUrls: transferUrlRecords.filter((r) => r.migrationStatus === "review").length,
    },

    dataIssues: {
      duplicateRoutes: mergedDestinations.length,
      conflictingPrices: recovery.priceConflicts.length,
      pagesNeedingManualReview: transferUrlRecords.filter((r) => r.migrationStatus === "review").map((r) => ({ sourceFile: r.sourceFile, reason: r.reason })),
      knownGaps: [
        "2 legacy pages (maafushi-island-transfer.html's sibling pattern) use a reversed 'NN$' price format in their title instead of '$NN' or JSON-LD — not extracted by this pass; both are low-value (already covered by an existing route or a generic hub page).",
        "New destination location names use the legacy page's own resort/brand name (e.g. 'Adaaran Select Hudhuranfushi') rather than a verified separate local island name, where the two might differ for a small number of properties — documented, not silently assumed to be identical.",
        "Hero images are only shown for destinations that already have a real, migrated accommodation photo (6 of 72 routes) — the ~55 new destinations recovered by this task have no photo yet rather than a generic stock substitute.",
      ],
    },
  };

  const outPath = path.join(MIGRATION_DATA_DIR, "task18-transfer-migration-report.json");
  writeFileSync(outPath, JSON.stringify(report, null, 2));

  console.log("Legacy inventory:", report.legacyInventory);
  console.log("Pricing:", { ...report.pricing, conflictingPrices: report.pricing.conflictingPrices.length });
  console.log("Destinations:", report.destinations);
  console.log("URLs:", report.urls);
  console.log("Data issues:", { duplicateRoutes: report.dataIssues.duplicateRoutes, conflictingPrices: report.dataIssues.conflictingPrices, pagesNeedingManualReview: report.dataIssues.pagesNeedingManualReview.length });
  console.log(`\nWrote ${path.relative(ROOT, outPath)}`);
}

main();
